const apply = () => { document.querySelectorAll('.error-summary a[href^="#"]').forEach((a) => { if (!a.getAttribute('href').startsWith('#step-')) a.setAttribute('href', '#step-' + a.getAttribute('href').slice(1)); }); };
const mo = new MutationObserver(() => { mo.disconnect(); apply(); mo.observe(document.body, { childList: true, subtree: true, attributes: true }); });
apply();
mo.observe(document.body, { childList: true, subtree: true, attributes: true });
